cat > dbg-caps.mjs <<'EOF'
import puppeteer from 'puppeteer-core';
import { spawn } from 'child_process';
const port = 3971;
const srv = spawn('node', ['server/index.js'], { cwd: '../app', env: { ...process.env, PORT: String(port) }, stdio: 'pipe' });
await new Promise(r => setTimeout(r, 900));
const browser = await puppeteer.launch({ executablePath: '/usr/bin/google-chrome-stable', headless: 'new',
  args: ['--no-sandbox','--use-gl=angle','--use-angle=swiftshader','--enable-unsafe-swiftshader'],
  defaultViewport: { width: 640, height: 360 } });
const page = await browser.newPage();
page.on('pageerror', e => console.log('ERR', e.message));
await page.goto(`http://127.0.0.1:${port}/`, { waitUntil: 'networkidle0' });
await page.waitForFunction('window.GAME && window.GAME.ready');
await page.evaluate(() => {
  GAME.test.setSetting('graphics.preset', 'balanced');
  GAME.test.start('vector'); GAME.test.skipBuy();
  const g = GAME.game;
  g.bots.forEach((b, i) => { b.pos = [-3 + i * 2, 0, 15]; b.yaw = Math.PI; });
  GAME.test.pose(0, 0, 21, 0, 0.02);
});
await new Promise(r => setTimeout(r, 600));
await page.screenshot({ path: 'dbg-caps-on.png' });
// strip capsules only
await page.evaluate(() => {
  const orig = GAME.game.renderBodies.bind(GAME.game);
  GAME.game.renderBodies = () => { const b = orig(); return { spheres: b.spheres, capsules: [] }; };
});
await new Promise(r => setTimeout(r, 600));
await page.screenshot({ path: 'dbg-caps-off.png' });
const counts = await page.evaluate(() => {
  const g = GAME.game;
  g.renderBodies = Object.getPrototypeOf(g).renderBodies.bind(g);
  const b = g.renderBodies();
  return { spheres: b.spheres.length, caps: b.capsules.length, sample: b.capsules[0] };
});
console.log(JSON.stringify(counts, null, 1));
await browser.close(); srv.kill();
EOF
node dbg-caps.mjs
